rows[64174]={title={{23,2121807671},"호디르의 보호의 시선"},description={"^allows hodir to save a friendly target who sustains fatal damage by encasing them in a nearly impenetrable block of ice for up to ([%+%-]?%d[%d,.]* %a+)%. hodir must rest after performing this action%.$","최대 \0311\031 동안 꿰뚫을 수 없는 얼음의 방패로 아군 대상을 보호하여 치명적인 피해를 견뎌낼 수 있게 합니다. 이 동작을 취한 후 호디르는 휴식이 필요합니다.",{1},{1}},aura={{72,1948459528},"죽음에 이를 수 있는 피해로부터 호디르가 구해줍니다."}}
