rows[65793]={title={{5,1188315097},"점멸"},description={"^teleports the caster ([%+%-]?%d[%d,.%+%-to –]*) yards forward, unless something is in the way%. also frees the caster from stuns and bonds%.$","시전자를 기절시키거나 구속하는 모든 것에서 벗어나 \0311\031미터 전방으로 순간이동합니다. 전방에는 장애물이 없어야 합니다.",{0},{1}},aura={{9,2046225448},"점멸 중"}}
