rows[65795]={title={{15,2064796377},"해방된 빛"},description={"^the light ball releases its energies inflicting ([%+%-]?%d[%d,.%+%-to –]*) light damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","빛구슬에서 방출된 에너지가 \0312\031미터 반경 내의 적에게 \0311\031의 빛의 피해를 입힙니다.",{0,0},{1,2}},aura={"^the light ball releases its energies inflicting ([%+%-]?%d[%d,.%+%-to –]*) light damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","빛구슬에서 에너지 방출\010\0312\031미터 반경 내의 적에게 \0311\031의 빛의 피해",{0,0},{1,2}}}
