rows[65797]={title={{8,835019210},"별똥별"},description={"^summon a flurry of stars from the sky on all targets within ([%+%-]?%d[%d,.%+%-to –]*) yards of the caster, each dealing ([%+%-]?%d[%d,.%+%-to –]*) arcane damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the enemy target%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","하늘에서 질풍과 같은 별똥별을 불러내어 시전자 주위 \0311\031미터 이내의 모든 대상에게 떨어뜨립니다. 대상으로부터 주변 \0313\031미터 이내에 있는 다른 모든 적들에게 \0312\031의 비전 피해를 입힙니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,2,3,4}}}
rows[65798]={title={{8,835019210},"별똥별"},description={"^summon a flurry of stars from the sky on all targets within ([%+%-]?%d[%d,.%+%-to –]*) yards of the caster, each dealing ([%+%-]?%d[%d,.%+%-to –]*) arcane damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards of the enemy target%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","하늘에서 질풍과 같은 별똥별을 불러내어 시전자 주위 \0311\031미터 이내의 모든 대상에게 떨어뜨립니다. 대상으로부터 주변 \0313\031미터 이내에 있는 다른 모든 적들에게 \0312\031의 비전 피해를 입힙니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,2,3,4}},aura={{29,1993290371},"하늘에서 별똥별 소환"}}
rows[65799]={title={{14,14523637},"비전 탄막"},description={"^launches several missiles at the enemy target, causing ([%+%-]?%d[%d,.%+%-to –]*) arcane damage%.$","적 대상에게 여러 발의 화살을 발사하여 \0311\031의 비전 피해를 입힙니다.",{0},{1}}}
rows[65800]={title={{16,1035566677},"신비한 폭발"},description={"^causes an explosion of arcane magic around the caster, causing ([%+%-]?%d[%d,.%+%-to –]*) arcane damage to all targets within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","시전자의 주위를 비전 마법의 힘으로 폭발시켜 \0312\031미터 반경에 있는 모든 적에게 \0311\031의 비전 피해를 입힙니다.",{0,0},{1,2}}}
rows[65801]={title={{9,1905076100},"변이"},description={"^transforms the enemy into a sheep, forcing it to wander around for up to ([%+%-]?%d[%d,.]* %a+)%. while wandering, the sheep cannot attack or cast spells%. any damage will transform the target back into its normal form%. only one target can be polymorphed at a time%. only works on beasts, humanoids and critters%.$","최대 \0311\031 동안 적을 양으로 변이시켜 주변을 떠돌게 만듭니다. 떠도는 동안엔 공격하거나 주문을 외울 수 없습니다. 이 동안 공격을 받으면 원래 모습으로 돌아옵니다. 동시에 한 대상만 변이시킬 수 있으며 야수와 인간형, 동물에게만 사용할 수 있습니다.",{1},{1}},aura={{29,907692239},"마법 시전 및 공격 불가"}}
rows[65802]={title={{9,1960685663},"얼음 방패"},description={"^you become encased in a block of ice, protecting you from all physical attacks and spells for ([%+%-]?%d[%d,.]* %a+), but during that time you cannot attack, move or cast spells%. also causes hypothermia, preventing you from recasting ice block for ([%+%-]?%d[%d,.]* %a+)%.$","커다란 얼음 덩어리에 둘러싸여 \0311\031 동안 모든 물리 공격과 주문으로부터 보호받습니다. 하지만 이 동안은 공격하거나 이동하거나 마법을 사용하지 못합니다. 또한 저체온증을 유발하여, \0312\031 동안은 얼음 방패를 다시 시전하지 못합니다.",{1,1},{1,2}},aura={{68,56642901},"모든 공격 및 주문에 면역\010공격, 이동, 주문 사용 불가"}}
