rows[65807]={title={{9,1999415615},"얼음 화살"},description={"^launches a bolt of frost at the enemy, causing ([%+%-]?%d[%d,.%+%-to –]*) frost damage and slowing movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 얼음 화살을 날려 \0311\031의 냉기 피해를 입히고 \0313\031 동안 이동 속도를 \0312\031%만큼 감소시킵니다.",{0,0,1},{1,2,3}},aura={"^movement slowed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
rows[65808]={title={{14,1210723597},"해방된 어둠"},description={"^the concentrated darkness releases its energies inflicting ([%+%-]?%d[%d,.%+%-to –]*) dark damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","결집된 어둠에서 방출된 에너지가 \0312\031미터 반경 내의 적에게 \0311\031의 어둠의 피해를 입힙니다.",{0,0},{1,2}},aura={"^the concentrated darkness releases its energies inflicting ([%+%-]?%d[%d,.%+%-to –]*) dark damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","결집된 어둠에서 에너지 방출\010\0312\031미터 반경 내의 적에게 \0311\031의 어둠의 피해",{0,0},{1,2}}}
rows[65809]={title={{4,231051364},"공포"},description={"^strikes fear in the enemy, causing it to run in fear for up to ([%+%-]?%d[%d,.]* %a+)%. damage caused may interrupt the effect%. only 1 target can be feared at a time%.$","적을 공포에 사로잡히게 하여 최대 \0311\031 동안 시전자로부터 도망갑니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다. 동시에 한 대상에게만 공포를 사용할 수 있습니다.",{1},{1}},aura={{7,1886574406},"겁에 질림"}}
rows[65810]={title={{10,525963311},"부패"},description={"^corrupts the target, causing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage over ([%+%-]?%d[%d,.]* %a+)%.$","대상을 부패시켜 \0312\031에 걸쳐 총 \0311\031의 암흑 피해를 입힙니다.",{0,1},{1,2}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0312\031초마다 \0311\031의 암흑 피해",{0,0},{1,2}}}
