rows[65812]={title={{19,480208245},"불안정한 고통"},description={"^shadow energy slowly destroys the target, causing ([%+%-]?%d[%d,.%+%-to –]*) damage over ([%+%-]?%d[%d,.]* %a+)%. in addition, if the unstable affliction is dispelled it will cause ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to the dispeller and silence them for ([%+%-]?%d[%d,.]* %a+)%.$","어둠의 기운이 천천히 대상을 파괴하여, \0312\031에 걸쳐 \0311\031의 피해를 입힙니다. 만약 불안정한 고통이 무효화되면, 무효화한 자는 \0313\031의 암흑 피해를 입고 \0314\031 동안 침묵 상태가 됩니다.",{0,1,0,1},{1,2,3,4}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. if dispelled, will cause ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to the dispeller and silence them for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031초마다 \0311\031의 암흑 피해\010무효화되면 무효화한 시전자는 \0313\031의 암흑 피해 및 \0314\031 동안 침묵",{0,0,0,1},{1,2,3,4}}}
rows[65813]={title={{19,480208245},"불안정한 고통"},description={"^when unstable affliction is dispelled, the dispeller suffers ([%+%-]?%d[%d,.%+%-to –]*) shadow damage and is silenced for ([%+%-]?%d[%d,.]* %a+)%.$","불안정한 고통이 무효화되면, 무효화한 자는 \0311\031의 암흑 피해를 입고 \0312\031 동안 침묵 상태가 됩니다.",{0,1},{1,2}},aura={{9,1628684605},"침묵 중"}}
rows[65814]={title={{14,1717357294},"고통의 저주"},description={"^curses the target with agony, causing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage over ([%+%-]?%d[%d,.]* %a+)%. this damage is dealt slowly at first, and builds up as the curse reaches its full duration%. only one curse per warlock can be active on any one target%.$","고통의 저주를 걸어 \0312\031에 걸쳐 \0311\031의 암흑 피해를 입힙니다. 처음엔 피해를 천천히 입히다가 갈수록 피해를 주는 속도가 빨라집니다. 흑마법사마다 대상에 동시에 하나의 저주만 걸 수 있습니다.",{0,1},{1,2}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) shadow damage over ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031에 걸쳐 총 \0311\031의 암흑 피해",{0,1},{1,2}}}
rows[65815]={title={{19,2044759677},"피로의 저주"},description={"^reduces the target's movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. only one curse per warlock can be active on any one target%.$","\0312\031 동안 대상의 이동 속도를 \0311\031%만큼 감소시킵니다. 흑마법사마다 한 대상에 하나의 저주만 걸 수 있습니다.",{0,1},{1,2}},aura={"^movement speed slowed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
