rows[65854]={title={{8,835157277},"별빛 섬광"},description={"^causes ([%+%-]?%d[%d,.%+%-to –]*) arcane damage to the target%.$","대상에게 \0311\031의 비전 피해를 입힙니다.",{0},{1}}}
rows[65855]={title={{12,816066969},"곤충 떼"},description={"^the enemy target is swarmed by insects, decreasing their chance to hit with melee and ranged attacks by ([%+%-]?%d[%d,.%+%-to –]*)%% and causing ([%+%-]?%d[%d,.%+%-to –]*) nature damage over ([%+%-]?%d[%d,.]* %a+)%.$","적이 곤충 떼에게 둘러싸여 근접 및 원거리 적중률이 \0311\031%만큼 감소되고 \0313\031에 걸쳐 총 \0312\031의 자연 피해를 입습니다.",{0,0,1},{1,2,3}},aura={"^chance to hit with melee and ranged attacks decreased by ([%+%-]?%d[%d,.%+%-to –]*)%% and ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","근접 및 원거리 적중률 \0311\031%만큼 감소\010\0313\031초마다 \0312\031의 자연 피해",{0,0,0},{1,2,3}}}
rows[65856]={title={{8,1490080242},"달빛 섬광"},description={"^burns the enemy for ([%+%-]?%d[%d,.%+%-to –]*) arcane damage and then an additional ([%+%-]?%d[%d,.%+%-to –]*) arcane damage over ([%+%-]?%d[%d,.]* %a+)%.$","적을 불태워 \0311\031의 비전 피해를 입히고 \0313\031에 걸쳐 총 \0312\031의 비전 피해를 입힙니다.",{0,0,1},{1,2,3}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) arcane damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0312\031초마다 \0311\031의 비전 피해",{0,0},{1,2}}}
rows[65857]={title={{16,1792209430},"휘감는 뿌리"},description={"^roots the target in place and causes ([%+%-]?%d[%d,.%+%-to –]*) nature damage over ([%+%-]?%d[%d,.]* %a+)%. damage caused may interrupt the effect%.$","대상을 제자리에 묶어 \0312\031에 걸쳐 총 \0311\031의 자연 피해를 입힙니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다.",{0,1},{1,2}},aura={"^rooted%. causes ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","이동 불가\010\0312\031초마다 \0311\031의 자연 피해",{0,0},{1,2}}}
rows[65858]={title={{16,371544394},"빛의 방패"},description={"^a shield of lights that protects the sister from harm absorbing ([%+%-]?%d[%d,.%+%-to –]*) damage and prevents spell interruption for ([%+%-]?%d[%d,.]* %a+)%.$","자매를 공격으로부터 보호하는 빛의 방패로 \0312\031 동안 \0311\031의 피해를 흡수하고 주문 시전이 지연되지 않도록 합니다.",{0,1},{1,2}},aura={{37,2009197530},"피해 흡수\010주문 방해 효과에 면역"}}
rows[65859]={title={{7,453053754},"회오리바람"},description={"^tosses the enemy target into the air, preventing all action but making them invulnerable for up to ([%+%-]?%d[%d,.]* %a+)%. only one target can be affected by your cyclone at a time%.$","적을 공중으로 날려보내, \0311\031 동안 어떠한 행동도 할 수 없지만 무적 상태가 되도록 합니다. 회오리바람은 동시에 한 대상에게만 사용할 수 있습니다.",{1},{1}},aura={{32,1161520391},"무적 상태\010모든 행동 불가"}}
rows[65860]={title={{8,354090432},"나무 껍질"},description={"^the druid's skin becomes as tough as bark%. all damage taken is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. this spell is usable while stunned, frozen, incapacitated, feared or asleep%. usable in all forms%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","드루이드의 피부가 나무 껍질처럼 단단해 집니다. 받는 모든 피해가 \0311\031%만큼 감소합니다. 기절, 얼어붙음, 행동 불가나 공포 상태에서도 사용할 수 있습니다. 인간형 혹은 모든 변신 상태에서 사용할 수 있습니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^all damage taken is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. while protected, damaging attacks will not cause spellcasting delays%.$","받는 모든 피해 \0311\031%만큼 감소\010공격에 의해 시전 시간 지연되지 않음",{0},{1}}}
rows[65861]={title={{15,468667192},"자연의 군대"},description={"^summons ([%+%-]?%d[%d,.%+%-to –]*) treants to attack enemy targets for ([%+%-]?%d[%d,.]* %a+)%.$","나무정령 \0311\031마리를 소환하여 전투를 돕게 합니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}}}
