rows[65863]={title={{11,399969998},"요정의 불꽃"},description={"^decrease the armor of the target by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. while affected, the target cannot stealth or turn invisible%.$","\0312\031 동안 대상의 방어도를 \0311\031%만큼 감소시킵니다. 효과가 지속되는 동안은 은신이나 투명화가 불가능합니다.",{0,1},{1,2}},aura={"^decreases armor by ([%+%-]?%d[%d,.%+%-to –]*)%%%. cannot stealth or turn invisible%.$","방어도 \0311\031%만큼 감소\010은신이나 투명화 불가",{0},{1}}}
rows[65864]={title={{4,226626564},"강하"},description={"^increases your movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031 동안 이동 속도가 \0311\031%만큼 증가합니다.",{0,1},{1,2}},aura={"^increases movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 증가",{0},{1}}}
