rows[65866]={title={{14,1048864920},"폭발 사격"},description={"^you fire an explosive charge into the enemy target, dealing ([%+%-]?%d[%d,.%+%-to –]*) fire damage%. the charge will blast the target every second for an additional ([%+%-]?%d[%d,.]* %a+)%.$","폭발의 화살이나 탄환을 발사하여 적 대상에게 \0311\031의 화염 피해를 입힙니다. 추가로 \0312\031 동안 1초마다 대상을 폭발하게 만듭니다.",{0,1},{1,2}},aura={{32,1466873251},"1초마다 화염 피해"}}
