rows[65877]={title={{12,754851131},"비룡 쐐기"},description={"^a stinging shot that puts the target to sleep for ([%+%-]?%d[%d,.]* %a+)%. any damage will cancel the effect%. when the target wakes up, the sting causes ([%+%-]?%d[%d,.%+%-to –]*) nature damage over ([%+%-]?%d[%d,.]* %a+)%. only one sting per hunter can be active on the target at a time%.$","적에게 쐐기를 발사하여 \0311\031 동안 잠재웁니다. 대상이 피해를 입으면 깨어납니다. 대상이 깨어나면 쐐기는 \0313\031에 걸쳐 \0312\031의 자연 피해를 입힙니다. 사냥꾼마다 한 번에 하나의 대상에게만 사용할 수 있습니다.",{1,0,1},{1,2,3}},aura={{7,1770695193},"수면 중"}}
