rows[65879]={title={{18,2004965239},"쌍둥이의 힘"},description={"^the shared power of the twins increases physical damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%% and allows the twin to dual wield for ([%+%-]?%d[%d,.]* %a+)%.$","쌍둥이가 힘을 합쳐 \0312\031 동안 물리 공격력이 \0311\031%만큼 증가하고 쌍수 무기를 들 수 있습니다.",{0,1},{1,2}},aura={"^increases physical damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%%%. dual wielding%.$","물리 공격력 \0311\031%만큼 증가\010쌍수 무기 사용",{0},{1}}}
rows[65880]={title={{10,1979623359},"냉기의 덫"},description={"^place a frost trap that creates an ice slick around itself for ([%+%-]?%d[%d,.]* %a+) when the first enemy approaches it%. all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards will be slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% while in the area of effect%. trap will exist for ([%+%-]?%d[%d,.]* %a+)%. only one trap can be active at a time%.$","냉기 덫을 설치합니다. 적이 다가오면 얇은 얼음판을 펼쳐, \0311\031 동안 \0312\031미터 반경 내에 있는 모든 적의 이동 속도를 \0313\031%만큼 감소시킵니다. 덫은 \0314\031 동안 지속되며, 한 개만 놓아둘 수 있습니다.",{1,0,0,1},{1,2,3,4}}}
rows[65881]={title={{11,1259376853},"살무사 쐐기"},description={"^stings the target, draining ([%+%-]?%d[%d,.%+%-to –]*) mana over ([%+%-]?%d[%d,.]* %a+)%. only one sting per hunter can be active on any one target%.$","쐐기를 대상에게 발사하여 \0312\031에 걸쳐 총 \0311\031의 마나를 소진시킵니다. 사냥꾼마다 한 대상에 동시에 하나의 쐐기만 사용할 수 있습니다.",{0,1},{1,2}},aura={"^drains ([%+%-]?%d[%d,.%+%-to –]*) mana every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0312\031초마다 \0311\031의 마나 흡수",{0,0},{1,2}}}
