rows[65973]={title={{11,1478340115},"대지 충격"},description={"^instantly shocks the target with concussive force, causing ([%+%-]?%d[%d,.%+%-to –]*) nature damage%. it also interrupts spellcasting and prevents any spell in that school from being cast for ([%+%-]?%d[%d,.]* %a+)%.$","시전 즉시 대상을 진동하는 힘으로 감싸 \0311\031의 자연 피해를 입히고, 대상이 \0312\031 동안 같은 계열의 주문을 시전하는 것을 방해합니다.",{0,1},{1,2}}}
rows[65974]={title={{9,777837513},"용암 채찍"},description={"^you charge your off%-hand weapon with lava, instantly dealing ([%+%-]?%d[%d,.%+%-to –]*)%% off%-hand weapon damage%. damage is increased by ([%+%-]?%d[%d,.%+%-to –]*)%% if your off%-hand weapon is enchanted with flametongue%.$","보조 무기에 용암의 열기를 주입하여 즉시 적 대상에게 보조 무기 공격력의 \0311\031%에 해당하는 피해를 입힙니다. 보조 무기에 불꽃의 무기 효과가 활성화되어 있으면 피해가 \0312\031%만큼 증가합니다.",{0,0},{1,2}}}
