rows[65978]={title={{18,74552561},"불꽃의 공격"},description={{197,1161609656},"주술사의 무기에 불의 기운을 부여하여 전체 주문 공격력을 증가시킵니다. 공격 적중 시 무기의 공격 속도에 따라 화염 피해를 입힙니다. 속도가 느린 무기는 한 번에 더 많은 화염 피해를 입힙니다. 30분 동안 지속됩니다."}}
