rows[65986]={title={{16,471148632},"소용돌이치는 무기"},description={"^reduces the cast time of your next lightning bolt, chain lightning, lesser healing wave, healing wave or chain heal spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","다음 번개 화살, 연쇄 번개, 하급 치유의 물결, 치유의 물결, 연쇄 치유 주문의 시전 시간이 \0311\031%만큼 감소합니다.",{0},{1}},aura={"^reduces the cast time of your next lightning bolt, chain lightning, lesser healing wave, healing wave or chain heal spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","다음 번개 화살, 연쇄 번개, 하급 치유의 물결, 치유의 물결, 연쇄 치유 주문의 시전 시간 \0311\031%만큼 감소",{0},{1}}}
rows[65987]={title={{14,632328013},"번개 화살"},description={"^blasts an enemy with lightning, inflicting ([%+%-]?%d[%d,.%+%-to –]*) nature damage%.$","적을 번개로 강타하여 \0311\031의 자연 피해를 입힙니다.",{0},{1}}}
rows[65988]={title={{16,471148632},"소용돌이치는 무기"},description={"^when you deal damage with a melee weapon, you have a chance to reduce the cast time of your next lightning bolt, chain lightning, lesser healing wave, chain heal or healing wave spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%. stacks up to 5 times%.$","근접 공격으로 피해를 입히면 일정 확률로 다음 번개 화살, 연쇄 번개, 하급 치유의 물결, 연쇄 치유, 치유의 물결 주문의 시전 시간이 \0311\031%만큼 감소합니다. 5번까지 중복됩니다.",{0},{1}}}
rows[65989]={title={{15,85982308},"마법흡수 토템"},description={"^summons a grounding totem with ([%+%-]?%d[%d,.%+%-to –]*) health at the feet of the caster that will redirect one harmful spell cast on a nearby party member to itself, destroying the totem%. will not redirect area of effect spells%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","시전자의 위치에 \0311\031의 생명력을 지닌 마법흡수 토템을 소환합니다. 주위 파티원을 대상으로 시전되는 해로운 주문 1개의 목표가 마법흡수 토템으로 바뀌고, 토템은 파괴됩니다. 광역 주문은 목표를 바꿀 수 없습니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}}}
rows[65990]={title={{14,224640890},"질풍의 토템"},description={"^summons a windfury totem with ([%+%-]?%d[%d,.%+%-to –]*) health at the feet of the caster%. the totem provides ([%+%-]?%d[%d,.%+%-to –]*)%% melee haste to all party and raid members within ([%+%-]?%d[%d,.%+%-to –]*) yards%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","시전자의 위치에 \0311\031의 생명력을 지닌 질풍의 토템을 소환하여 주위 \0313\031미터 반경 내에 있는 모든 파티원과 공격대원의 근접 가속을 \0312\031%만큼 증가시킵니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,2,3,4}},aura={"^increases melee haste by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","근접 가속 \0311\031%만큼 증가",{0},{1}}}
rows[65991]={title={{23,702379418},"대지력 토템"},description={"^summons a strength of earth totem with ([%+%-]?%d[%d,.%+%-to –]*) health at the feet of the caster%. the totem increases the strength and agility by ([%+%-]?%d[%d,.%+%-to –]*) to all party and raid members within ([%+%-]?%d[%d,.%+%-to –]*) yards%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","시전자의 위치에 \0311\031의 생명력을 지닌 대지력 토템을 소환하여, 주위 \0313\031미터 반경 내의 파티원과 공격대원의 힘과 민첩성을 \0312\031만큼 증가시킵니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,2,3,4}}}
rows[65992]={title={{12,1199202458},"진동의 토템"},description={"^summons a tremor totem with ([%+%-]?%d[%d,.%+%-to –]*) health at the feet of the caster that shakes the ground around it, removing fear, charm and sleep effects from party members within ([%+%-]?%d[%d,.%+%-to –]*) yards%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","시전자의 위치에 생명력 \0311\031의 진동의 토템을 소환합니다. 이 토템은 땅을 울려 주위 \0312\031미터 반경 내의 파티원에게 걸린 공포, 현혹, 수면 효과를 제거합니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}}}
rows[65993]={title={{20,1415007455},"치유의 토템"},description={"^restores ([%+%-]?%d[%d,.%+%-to –]*) health to nearby allies%.$","주위 아군의 생명력을 \0311\031만큼 회복시킵니다.",{0},{1}}}
rows[65994]={title={{14,1538331906},"치유의 흐름"},description={"^restores health every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0311\031초마다 생명력이 회복됩니다.",{0},{1}},aura={"^restores health every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0311\031초마다 생명력 회복",{0},{1}}}
rows[65995]={title={{20,1415007455},"치유의 토템"},description={"^summons a healing stream totem with ([%+%-]?%d[%d,.%+%-to –]*) health at the feet of the caster for ([%+%-]?%d[%d,.]* %a+) that heals group members within ([%+%-]?%d[%d,.%+%-to –]*) yards for ([%+%-]?%d[%d,.%+%-to –]*) every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","시전자의 위치에 \0311\031의 생명력을 지닌 치유의 토템을 소환하여, 주위 \0313\031미터 반경 내에 있는 파티원의 생명력을 \0315\031초마다 \0314\031만큼 회복시킵니다. \0312\031 동안 지속됩니다.",{0,1,0,0,0},{1,2,3,4,5}}}
