rows[66001]={title={{17,877078342},"어둠의 손길"},description={"^the val'kyr's dark touch has affected you, inflicting ([%+%-]?%d[%d,.%+%-to –]*) dark damage to players under the effect of light essence every ([%+%-]?%d[%d,.%+%-to –]*) sec%. the touch of darkness will not harm targets with the same attributes as it%.$","발키르의 어둠의 손길을 받아 빛의 정수 효과를 얻은 플레이어에게 \0312\031초마다 \0311\031의 어둠의 피해를 입힙니다. 동일한 속성의 대상에게는 피해를 입히지 않습니다.",{0,0},{1,2}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) dark damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. touch of darkness will not harm dark targets%.$","\0312\031초마다 \0311\031의 어둠의 피해\010어둠의 대상에게는 피해를 입히지 않음",{0,0},{1,2}}}
