rows[66008]={title={{10,932325501},"참회"},description={"^puts the enemy target in a state of meditation, incapacitating them for up to ([%+%-]?%d[%d,.]* %a+)%. any damage caused will awaken the target%. usable against demons, dragonkin, giants, humanoids and undead%.$","적을 최대 \0311\031 동안 회고의 시간을 가지게 하여 행동 불가 상태로 만듭니다. 대상이 피해를 입으면 깨어납니다. 악마, 용족, 거인, 인간형, 언데드에게 사용할 수 있습니다.",{1},{1}},aura={{14,1272202554},"행동 불가"}}
rows[66009]={title={{18,149727582},"보호의 손길"},description={"^a targeted ally member is protected from all physical attacks for ([%+%-]?%d[%d,.]* %a+)%.$","대상 아군은 \0311\031 동안 모든 물리 공격으로부터 보호받습니다.",{1},{1}},aura={{27,223389196},"물리 공격에 면역"}}
rows[66010]={title={{13,837500609},"천상의 보호막"},description={"^protects the paladin from all damage and spells for ([%+%-]?%d[%d,.]* %a+), but reduces all damage you deal by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0311\031 동안 모든 공격과 주문으로부터 자신을 보호하지만 공격력이 \0312\031%만큼 감소합니다.",{1,0},{1,2}},aura={"^immune to all attacks and spells, but reduces all damage you deal by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","모든 공격 및 주문에 면역\010공격력 \0311\031%만큼 감소",{0},{1}}}
rows[66011]={title={{14,1932523089},"응징의 격노"},description={"^increases all damage and healing caused by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031 동안 모든 공격력과 치유량이 \0311\031%만큼 증가합니다.",{0,1},{1,2}},aura={"^all damage and healing caused increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","모든 공격력 및 치유량 \0311\031%만큼 증가",{0},{1}}}
rows[66012]={title={{14,544438914},"얼음 베기"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*)%% froststrike damage to an enemy and freezes it in a block of ice for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 냉기충격을 가하여 \0311\031%의 피해를 입히고 \0312\031 동안 얼음 덩어리에 가둡니다.",{0,1},{1,2}},aura={{8,318235535},"기절함"}}
rows[66013]={title={{16,546709048},"냉기 관통"},description={"^penetrating cold sinks into several enemy targets, inflicting ([%+%-]?%d[%d,.%+%-to –]*) frost damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","여러 명의 대상에게 \0312\031초마다 \0311\031의 냉기 피해를 입힙니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) frost damage inflicted every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 냉기 피해",{0,0},{1,2}}}
