rows[66020]={title={{13,988110214},"얼음 결계"},description={"^shackles the target with frozen chains, reducing their movement to 5%% of normal%. the target regains 10%% of their movement each second for ([%+%-]?%d[%d,.]* %a+)%.$","대상을 얼음의 사슬로 속박하여 이동 속도를 평소의 5%로 감소시킵니다. 대상은 1초마다 이동 속도를 10%씩 회복합니다. \0311\031 동안 지속됩니다.",{1},{1}},aura={{23,1015165722},"이동 속도 감소"}}
