rows[70447]={title={{22,1550473853},"일촉즉발 수액괴물 끈끈이"},description={"^the volatile ooze adhesive bonds the target to the volatile ooze, inflicting ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) sec and rooting the target%. the volatile ooze will move towards the target, exploding for ([%+%-]?%d[%d,.%+%-to –]*) damage, split among all nearby targets%.$","일촉즉발 수액괴물 끈끈이로 대상을 일촉즉발 수액괴물에 부착시켜 \0312\031초마다 \0311\031의 피해를 입히고 이동 불가 상태로 만듭니다. 일촉즉발 수액괴물은 대상을 향해 이동한 후 폭발하여 \0313\031의 피해를 입히고 분열하여 주위 모든 대상에게 퍼집니다.",{0,0,0},{1,2,3}},aura={"^rooted%. inflicts ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. when the volatile ooze reaches you, it will explode for ([%+%-]?%d[%d,.%+%-to –]*) damage, split among all nearby targets%.$","이동 불가\010\0312\031초마다 \0311\031의 피해\010일촉즉발 수액괴물이 근접해 오면 폭발하여 \0313\031의 피해를 입히고 분열하여 주위 모든 대상에게 퍼짐",{0,0,0},{1,2,3}}}
